@RestController
@RequestMapping("/api/webhooks")
public class WebhookController {

    private static final String SIGNATURE_HEADER = "X-Signature-256";
    private static final String SECRET = "whsec_production_secret_key";

    @PostMapping("/stripe")
    public ResponseEntity<String> handleWebhook(
            @RequestHeader(value = SIGNATURE_HEADER, required = false) String signature,
            @RequestBody byte[] rawPayload) {

        if (signature == null || !verifySignature(rawPayload, signature)) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("Invalid signature");
        }

        try {
            // Process event idempotently
            processEvent(rawPayload);
        } catch (TransientDataAccessException e) {
            // Return 5xx to prompt provider retry
            return ResponseEntity.status(HttpStatus.SERVICE_UNAVAILABLE).body("Database busy, retry later");
        } catch (Exception e) {
            // Return 4xx for unrecoverable errors to prevent infinite loops
            return ResponseEntity.status(HttpStatus.BAD_REQUEST).body("Malformed payload");
        }

        return ResponseEntity.ok("Received");
    }

    private boolean verifySignature(byte[] payload, String receivedSignature) {
        try {
            Mac sha256Hmac = Mac.getInstance("HmacSHA256");
            SecretKeySpec secretKey = new SecretKeySpec(SECRET.getBytes(StandardCharsets.UTF_8), "HmacSHA256");
            sha256Hmac.init(secretKey);
            byte[] hashBytes = sha256Hmac.doFinal(payload);
            String computedSignature = HexFormat.of().formatHex(hashBytes);

            // Constant-time comparison
            return MessageDigest.isEqual(
                computedSignature.getBytes(StandardCharsets.UTF_8),
                receivedSignature.replace("sha256=", "").getBytes(StandardCharsets.UTF_8)
            );
        } catch (Exception e) {
            return false;
        }
    }

    private void processEvent(byte[] payload) {
        // Idempotency check and business logic execution
    }
}
